import {SIZE,land,PLACES,MODES,TYPES,GOODS,atPath,dock} from './sim.mjs';
export const iso=(x,y)=>({x:(x-y)*29,y:(x+y)*14.5});
const poly=(c,p,color)=>{c.beginPath();p.forEach(([x,y],i)=>i?c.lineTo(x,y):c.moveTo(x,y));c.closePath();c.fillStyle=color;c.fill()};
const rect=(c,x,y,w,h,color,r=0)=>{c.fillStyle=color;c.beginPath();c.roundRect(x,y,w,h,r);c.fill()};
const line=(c,a,b,color,w=1)=>{c.strokeStyle=color;c.lineWidth=w;c.beginPath();c.moveTo(a.x,a.y);c.lineTo(b.x,b.y);c.stroke()};
const box=(c,x,y,w,d,h,color,roof)=>{const a=iso(x,y),b=iso(x+w,y),e=iso(x,y+d),f=iso(x+w,y+d);poly(c,[[a.x,a.y-h],[b.x,b.y-h],[f.x,f.y-h],[e.x,e.y-h]],roof||color);poly(c,[[e.x,e.y-h],[f.x,f.y-h],[f.x,f.y],[e.x,e.y]],color);poly(c,[[b.x,b.y-h],[f.x,f.y-h],[f.x,f.y],[b.x,b.y]],shade(color,-22));};
function shade(hex,n){const v=parseInt(hex.slice(1),16);return '#'+[v>>16,(v>>8)&255,v&255].map(x=>Math.max(0,Math.min(255,x+n)).toString(16).padStart(2,'0')).join('')}
function tree(c,x,y,size=1){const p=iso(x,y);rect(c,p.x-1.2,p.y-10*size,2.5,13*size,'#56654b');poly(c,[[p.x,p.y-34*size],[p.x-12*size,p.y-11*size],[p.x+12*size,p.y-11*size]],'#4d8060');poly(c,[[p.x,p.y-34*size],[p.x,p.y-11*size],[p.x+12*size,p.y-11*size]],'#3f7155');poly(c,[[p.x,p.y-24*size],[p.x-14*size,p.y-3*size],[p.x+14*size,p.y-3*size]],'#54866a');poly(c,[[p.x,p.y-24*size],[p.x,p.y-3*size],[p.x+14*size,p.y-3*size]],'#42775b')}
function house(c,x,y,level,seed){const h=10+level*8,p=iso(x+.35,y+.35),color=['#cbd0bb','#dfd4b6','#b9c7bd','#c8c3b6'][seed%4];box(c,x,y,.65,.65,h,color);const a=iso(x,y),b=iso(x+.65,y),e=iso(x,y+.65),f=iso(x+.65,y+.65);poly(c,[[a.x,a.y-h],[p.x,p.y-h-9],[b.x,b.y-h],[f.x,f.y-h]],seed%3?'#78918d':'#b77c62');poly(c,[[a.x,a.y-h],[p.x,p.y-h-9],[e.x,e.y-h],[f.x,f.y-h]],seed%3?'#65817c':'#9b6657');for(let k=0;k<level;k++){rect(c,p.x-10,p.y-7-k*7,3,4,'#688b99');rect(c,p.x+4,p.y-7-k*7,3,4,'#617e86')};}
function building(c,n,time){const x=n.x,y=n.y,p=iso(x,y);c.save();c.translate(0,-5);
 if(n.type==='city'){box(c,x-1.2,y-1.2,2.4,2.4,1,'#9aa68c','#b8c1a4');const tier=Math.min(4,1+Math.floor(n.pop/700));for(const [dx,dy,s]of [[-.9,-.85,1],[.1,-.9,2],[-.9,.1,3],[.15,.2,4]])house(c,x+dx,y+dy,Math.max(1,tier-(s%2)),n.id+s);box(c,x+.15,y-.1,.17,.16,23,'#9fbbb4','#dfe5cb');}
 else if(n.type==='forest'){for(const [dx,dy]of [[-1,-.5],[0,-1],[.8,-.6],[-.5,.6],[.6,.5]])tree(c,x+dx,y+dy,1.15);box(c,x-.4,y-.1,.8,.6,7,'#968367','#b8a27f');for(let i=0;i<4;i++){const q=iso(x+.6+i*.15,y+.7);line(c,q,{x:q.x+17,y:q.y-8},'#8e6947',5)}}
 else if(n.type==='farm'){box(c,x-1.5,y-1.2,3,2.5,1,'#a99b62','#d1b875');for(let i=0;i<8;i++)line(c,iso(x-1.3+i*.33,y-1),iso(x-1.3+i*.33,y+.9),'#9a9c61',2);house(c,x-.3,y-.2,1,0);box(c,x+.7,y-.1,.35,.35,20,'#d8d2ba','#eee5cf')}
 else if(n.type==='mine'){poly(c,[[p.x-39,p.y],[p.x-11,p.y-31],[p.x+22,p.y-26],[p.x+45,p.y+3],[p.x,p.y+22]],'#929892');poly(c,[[p.x-11,p.y-31],[p.x+2,p.y+12],[p.x+45,p.y+3],[p.x+22,p.y-26]],'#727f7d');rect(c,p.x-9,p.y-10,20,19,'#344955',8);box(c,x+.6,y+.3,.8,.4,13,'#ac9275','#d3b899')}
 else {box(c,x-1,y-.7,1.9,1.4,18,n.type==='foodplant'?'#ddd2b8':'#a7b6ad',n.type==='sawmill'?'#a9785e':'#809d9b');const a=iso(x-1,y-.7),b=iso(x+.9,y+.7);line(c,{x:a.x,y:a.y-20},{x:b.x,y:b.y-20},'#b9d0c8',2);for(let i=0;i<4;i++)rect(c,p.x-28+i*13,p.y-7,7,5,'#568f9b');box(c,x+.7,y-.6,.3,.3,n.type==='steelworks'?45:32,'#8c9891','#c6d0bf');if(n.type==='steelworks'){rect(c,p.x-10,p.y-3,10,8,'#e2a16a');}if(n.type==='factory'){const a=iso(x+1,y+1);line(c,a,{x:a.x,y:a.y-46},'#c1a269',4);line(c,{x:a.x,y:a.y-46},{x:a.x+37,y:a.y-56},'#c1a269',4);line(c,{x:a.x+32,y:a.y-55},{x:a.x+32,y:a.y-25},'#677d7c',1)}}
 c.restore();}
function vehicle(c,mode,x,y,angle,color,scale=1,time=0){c.save();c.translate(x,y);c.rotate(angle);c.scale(scale,scale);c.fillStyle='#0f36492b';c.beginPath();c.ellipse(1,4,mode==='ship'?17:13,5,0,0,Math.PI*2);c.fill();if(mode==='plane'){poly(c,[[0,-2],[9,-18],[13,-18],[9,-2],[22,0],[9,2],[13,18],[9,18],[0,2],[-12,8],[-15,7],[-9,1],[-16,0],[-9,-1],[-15,-7],[-12,-8]],'#f4eee0');line(c,{x:-9,y:0},{x:18,y:0},color,3);rect(c,11,-1.5,4,3,'#4d839b',1)}else if(mode==='ship'){poly(c,[[-22,-8],[14,-8],[24,0],[14,8],[-22,8],[-26,0]],'#f3e7cf');poly(c,[[-22,5],[15,5],[24,0],[14,10],[-22,10]],'#386277');rect(c,-17,-6,25,12,color,1);for(let i=0;i<3;i++)rect(c,-15+i*8,-5,6,9,['#bd835e','#8ca7a2','#d3b46c'][i]);rect(c,-20,-4,7,8,'#e8e9d7',1);rect(c,-19,-3,4,6,'#6299aa',1)}else{const len=mode==='train'?25:mode==='truck'?21:20;rect(c,-len/2,-6,len,13,'#394f56',3);for(const dx of [-7,6]){rect(c,dx,-7,4,3,'#30444b',1);rect(c,dx,5,4,3,'#30444b',1)}rect(c,-len/2,-6,len,10,color,2);rect(c,len/2-7,-5,5,8,'#c3e0dc',1);if(mode==='train'){rect(c,-9,-5,9,8,'#e7dcc3',1);rect(c,6,-4,3,6,'#578494');}else if(mode==='truck')rect(c,-10,-5,12,9,'#dfd9c4',1);else for(let i=0;i<3;i++)rect(c,-8+i*4,-5,3,8,'#afd4d4',1)}c.restore()}
export class World{
 constructor(canvas,onPick,onView){this.canvas=canvas;this.c=canvas.getContext('2d');this.onPick=onPick;this.onView=onView;this.zoom=1;this.pan={x:0,y:0};this.time=0;this.floats=[];this.hover=null;this.selected=null;this.preview=null;this.terrain();this.resize();this.pointers=new Map();this.bind();new ResizeObserver(()=>this.resize()).observe(canvas);}
 resize(){const r=this.canvas.getBoundingClientRect();this.w=r.width;this.h=r.height;const d=Math.min(devicePixelRatio||1,2);this.canvas.width=Math.round(this.w*d);this.canvas.height=Math.round(this.h*d);this.dpr=d;this.base=Math.min(this.w/1600,this.h/900);}
 project(x,y){const p=iso(x,y),s=this.base*this.zoom;return {x:this.w/2+this.pan.x+p.x*s,y:this.h/2+this.pan.y+(p.y-415)*s};}
 unproject(x,y){const s=this.base*this.zoom,px=(x-this.w/2-this.pan.x)/s,py=(y-this.h/2-this.pan.y)/s+415;return {x:py/29+px/58,y:py/29-px/58}}
 changeZoom(f){this.zoom=Math.max(.7,Math.min(3.8,this.zoom*f));this.onView?.()}
 focus(node){this.zoom=Math.max(1.5,this.zoom);const p=iso(node.x,node.y),s=this.base*this.zoom;this.pan={x:-p.x*s,y:-(p.y-415)*s};this.selected=node.id;}
 reset(){this.zoom=1;this.pan={x:0,y:0};this.onView?.()}
 bind(){let down=null,pinch=0;const relative=e=>{const r=this.canvas.getBoundingClientRect();return {x:e.clientX-r.left,y:e.clientY-r.top}};this.canvas.addEventListener('pointerdown',e=>{this.canvas.setPointerCapture(e.pointerId);const p=relative(e);this.pointers.set(e.pointerId,p);down={...p,moved:false};if(this.pointers.size===2){const a=[...this.pointers.values()];pinch=Math.hypot(a[0].x-a[1].x,a[0].y-a[1].y);down.moved=true}});this.canvas.addEventListener('pointermove',e=>{const p=relative(e);if(this.pointers.has(e.pointerId)){const old=this.pointers.get(e.pointerId);this.pointers.set(e.pointerId,p);if(this.pointers.size===2){const a=[...this.pointers.values()],d=Math.hypot(a[0].x-a[1].x,a[0].y-a[1].y);if(pinch)this.changeZoom(d/pinch);pinch=d;return}if(down&&(down.moved||Math.hypot(p.x-down.x,p.y-down.y)>5)){down.moved=true;this.pan.x+=p.x-old.x;this.pan.y+=p.y-old.y;}}else{const n=this.pick(p.x,p.y);this.hover=n?.id??null;this.canvas.style.cursor=n?'pointer':'grab'}});this.canvas.addEventListener('pointerup',e=>{const p=relative(e);this.pointers.delete(e.pointerId);if(down&&!down.moved){const n=this.pick(p.x,p.y);if(n)this.onPick(n.id)}if(this.pointers.size===0){down=null;pinch=0}});this.canvas.addEventListener('pointercancel',()=>{this.pointers.clear();down=null;pinch=0});this.canvas.addEventListener('wheel',e=>{e.preventDefault();this.changeZoom(e.deltaY>0?.9:1.1)},{passive:false});}
 pick(x,y){let result=null,best=38;for(const n of PLACES){const p=this.project(n.x,n.y),d=Math.hypot(x-p.x,y-(p.y-15*this.base*this.zoom));if(d<best){best=d;result=n}}return result}
 terrain(){this.bg=document.createElement('canvas');this.bg.width=1850;this.bg.height=1050;const c=this.bg.getContext('2d');c.translate(925,30);for(let sum=0;sum<SIZE*2;sum++)for(let x=0;x<SIZE;x++){const y=sum-x;if(y<0||y>=SIZE)continue;const p=iso(x,y);if(land(x,y)){const edge=[[1,0],[-1,0],[0,1],[0,-1]].some(([dx,dy])=>!land(x+dx,y+dy));const color=edge?'#c9c99c':['#8fa87d','#93ad82','#99af82','#9eb38a'][(x*17+y*7)%4];poly(c,[[p.x-29,p.y],[p.x,p.y+14.5],[p.x+29,p.y],[p.x,p.y-14.5]],'#7b9276');poly(c,[[p.x-29,p.y-5],[p.x,p.y+9.5],[p.x+29,p.y-5],[p.x,p.y-19.5]],color);line(c,{x:p.x-28,y:p.y-5},{x:p.x,y:p.y-19},'#c9d1ab20');}else if((x*13+y*5)%9===0){line(c,{x:p.x-10,y:p.y},{x:p.x+10,y:p.y},'#a9d1cf1c',1)}}
 for(let sum=0;sum<SIZE*2;sum++)for(let x=0;x<SIZE;x++){const y=sum-x;if(y<0||y>=SIZE||!land(x,y)||PLACES.some(n=>Math.hypot(x-n.x,y-n.y)<2.1))continue;if((x*23+y*17)%7===0)tree(c,x,y,.7+((x+y)%3)*.13);else if((x*7+y*13)%31===0){const p=iso(x,y);poly(c,[[p.x-9,p.y-5],[p.x-4,p.y-13],[p.x+6,p.y-12],[p.x+11,p.y-3]],'#8a9984')}}}
 draw(company,dt){this.time+=dt;const c=this.c,s=this.base*this.zoom;c.setTransform(this.dpr,0,0,this.dpr,0,0);const g=c.createLinearGradient(0,0,this.w,this.h);g.addColorStop(0,'#719caa');g.addColorStop(1,'#4f7e95');c.fillStyle=g;c.fillRect(0,0,this.w,this.h);c.save();c.translate(this.w/2+this.pan.x,this.h/2+this.pan.y-415*s);c.scale(s,s);for(let i=0;i<70;i++){const x=((i*137)%1600)-800,y=(i*89)%850;if(!land(Math.round(y/29+x/58),Math.round(y/29-x/58))){c.globalAlpha=.13+.07*Math.sin(this.time+i);line(c,{x:x+Math.sin(this.time*.3+i)*5,y},{x:x+15+Math.sin(this.time*.3+i)*5,y},'#cde0d5',1)}}c.globalAlpha=1;c.drawImage(this.bg,-925,-30);
 for(const r of company.routes)this.route(c,r.path,r.mode,r.enabled?1:.3,false);if(this.preview)this.route(c,this.preview.path,this.preview.mode,.8,true);
 for(const n of company.nodes){if(n.facilities.port){const p=iso(n.x,n.y),d=dock(n),q=iso(d.x,d.y);line(c,p,q,'#9d9882',12);line(c,p,q,'#c0b899',7);for(let i=0;i<3;i++)box(c,d.x+i*.18,d.y,.12,.12,9,'#85795f','#c2b68f')}
 if(n.facilities.air){box(c,n.x-1.4,n.y+1.2,2.8,.5,2,'#899b93','#5e7475');const a=iso(n.x-1.3,n.y+1.45),b=iso(n.x+1.3,n.y+1.45);c.setLineDash([4,4]);line(c,a,b,'#d7d3b7',1);c.setLineDash([]);box(c,n.x-1.5,n.y+.7,.3,.3,25,'#c8d0bb','#6c9a9d')}
 if(n.facilities.rail)box(c,n.x-1,n.y+1,2,.35,5,'#a7a890','#d4c8a5');if(n.facilities.road){const p=iso(n.x+1.4,n.y);rect(c,p.x,p.y-15,3,15,'#6f8584');rect(c,p.x-4,p.y-17,11,7,'#d0ae6b',1)}}
 for(const n of [...company.nodes].sort((a,b)=>a.x+a.y-b.x-b.y)){
 building(c,n,this.time);
 const count=Math.min(8,Math.floor((n.stock[TYPES[n.type].out]||0)/22));
 if(n.type==='city'&&Object.keys(n.facilities).length){for(let i=0;i<count;i++){const p=iso(n.x-.7+i*.16,n.y+1.05);rect(c,p.x-1,p.y-6,2,5,['#66778b','#b88a6a','#809b82'][i%3],1);c.fillStyle='#dfc9a4';c.beginPath();c.arc(p.x,p.y-7,1.3,0,7);c.fill()}}
 else if(n.type!=='city'){for(let i=0;i<count;i++)box(c,n.x+.65+(i%4)*.18,n.y+.65+Math.floor(i/4)*.2,.15,.17,4,'#9f9872','#d1c39b');}
 }
 for(const r of company.routes){for(const v of r.vehicles){const p=atPath(r.path,v.progress),q=atPath(r.path,Math.max(0,Math.min(1,v.progress+v.dir*.006))),a=iso(p.x,p.y),b=iso(q.x,q.y),angle=Math.atan2(b.y-a.y,b.x-a.x);if(r.mode==='train'){for(let i=2;i>=1;i--){const prev=atPath(r.path,Math.max(0,Math.min(1,v.progress-v.dir*i*.48/r.distance))),ap=iso(prev.x,prev.y);vehicle(c,'truck',ap.x,ap.y-6,angle,MODES[r.mode].color,.75,this.time)}}
 if(r.mode==='ship'&&v.wait<=0){c.setLineDash([6,4]);line(c,{x:a.x-Math.cos(angle)*40,y:a.y-Math.sin(angle)*40},a,'#cfdfd669',3);c.setLineDash([])}if(r.mode==='plane'){c.globalAlpha=.14;vehicle(c,'plane',a.x+12,a.y+10,angle,'#31444a');c.globalAlpha=1}vehicle(c,r.mode,a.x,a.y-(r.mode==='plane'?(v.wait>0?0:Math.min(1,v.progress*8,(1-v.progress)*8)*35):6),angle,MODES[r.mode].color,r.mode==='train'?.85:1,this.time);if(v.load>0&&this.zoom>1.5){c.font='8px monospace';c.fillStyle='#fff7df';c.fillText(v.load,a.x-4,a.y-19)}}}
 // Chimney smoke drifts above industry roofs.
 for(const n of company.nodes.filter(n=>['steelworks','factory','foodplant'].includes(n.type))){const p=iso(n.x+.8,n.y-.5);for(let i=0;i<3;i++){const t=(this.time*.3+i*.32)%1;c.globalAlpha=(1-t)*.22;c.fillStyle='#e2e5cf';c.beginPath();c.arc(p.x+t*14,p.y-35-t*40,3+t*7,0,7);c.fill()}c.globalAlpha=1}
 c.restore();
 for(const f of company.visuals.splice(0))this.floats.push({...f,life:2});
 for(const f of this.floats){f.life-=dt;const n=company.nodes[f.node],p=this.project(n.x,n.y);c.globalAlpha=Math.min(1,f.life);c.font='600 12px system-ui';const text='+'+f.income.toLocaleString(),tw=c.measureText(text).width;rect(c,p.x-tw/2-7,p.y-55-(2-f.life)*18,tw+14,22,'#f6efddeb',5);c.fillStyle='#487759';c.fillText(text,p.x-tw/2,p.y-39-(2-f.life)*18);c.globalAlpha=1}this.floats=this.floats.filter(f=>f.life>0).slice(-20);
 for(const n of company.nodes){const p=this.project(n.x,n.y),active=this.selected===n.id||this.hover===n.id;const color=n.type==='city'?'#f0e7d3':'#d9e2cf';c.font=`${active?'600':'500'} ${Math.max(9,Math.min(12,10*this.zoom))}px system-ui`;const tw=c.measureText(n.name).width,x=p.x-tw/2,y=p.y+18*s;if(p.x<-100||p.x>this.w+100||y<0||y>this.h)continue;rect(c,x-7,y-11,tw+14,20,active?'#263f4aee':'#1d3a478c',4);c.fillStyle=active?'#fff4d6':color;c.fillText(n.name,x,y+3);if(active){c.strokeStyle='#f0cf8d';c.lineWidth=1.5;c.beginPath();c.ellipse(p.x,p.y-4*s,38*s,19*s,0,0,Math.PI*2);c.stroke()}}
 }
 route(c,path,mode,alpha=1,preview=false){if(!path?.length)return;c.save();c.globalAlpha=alpha;const points=path.map(p=>iso(p.x,p.y));const draw=(color,width,dash=[])=>{c.setLineDash(dash);c.strokeStyle=color;c.lineWidth=width;c.lineJoin='round';c.lineCap='round';c.beginPath();points.forEach((p,i)=>i?c.lineTo(p.x,p.y-4):c.moveTo(p.x,p.y-4));c.stroke()};if(preview){draw('#f6d194',5,[8,6]);c.restore();return}if(mode==='ship'||mode==='plane'){draw(MODES[mode].color,1.5,[6,9]);}else{for(let i=1;i<path.length;i++)if(!land(path[i].x,path[i].y)){const p=points[i];line(c,{x:p.x,y:p.y+10},{x:p.x,y:p.y-4},'#a0a58b',4)}if(mode==='train'){draw('#7d8071',8);draw('#b9b49b',5,[2,5]);draw('#4c6665',2);}else{draw('#c4c1a3',9);draw('#778d89',6);draw('#d1d3b5',.7,[4,5]);}}c.restore();}
}
